using System.Collections.Generic;public static class WordPattern{public static bool Check(string p,string s){string[] w=s.Split(' ');if(w.Length!=p.Length)return false;var a=new Dictionary<char,string>();var b=new Dictionary<string,char>();for(int i=0;i<p.Length;i++){if(a.ContainsKey(p[i])&&a[p[i]]!=w[i]||b.ContainsKey(w[i])&&b[w[i]]!=p[i])return false;a[p[i]]=w[i];b[w[i]]=p[i];}return true;}}